#include "lynq/ui/HubDashboardComposer.h"
#include <cassert>
int main(){using namespace lynq::ui; HubDashboardInput i; i.hubName="Tavis Home"; i.connection={true,true,true,2,0}; i.devices={{"tv","TV","Living","television",true,true,false},{"pool","Pool","Backyard","light",true,true,true}}; i.scenes={{"movie","Movie Night","4 actions",true}}; i.automations={{"morning","Morning","7:30",true}}; i.activity={{"a1","alexa","TV on","ok",true,1},{"a2","scene","Movie","ok",true,2}}; auto v=HubDashboardComposer::compose(i); assert(v.title=="Tavis Home"); assert(v.favoriteDevices.size()==2); assert(v.recentActivity.front().activityId=="a2"); i.connection.cloudConnected=false; assert(HubDashboardComposer::compose(i).showOfflineBanner); HubDashboardInput e; assert(HubDashboardComposer::compose(e).showOnboarding);}
